"use client";

import { useEffect, useState } from "react";
import type { Transition } from "motion/react";
import { useHydratedReducedMotion } from "@/lib/use-reduced-motion";
import { cn } from "@/lib/utils";

export { cn, useHydratedReducedMotion };

export type MomentProps = {
  className?: string;
  preview?: boolean;
};

export const springFast: Transition = { type: "spring", stiffness: 620, damping: 32 };
export const springSoft: Transition = { type: "spring", stiffness: 260, damping: 22 };
export const springBounce: Transition = { type: "spring", stiffness: 380, damping: 18 };
export const springHeavy: Transition = { type: "spring", stiffness: 200, damping: 26 };
export const springSnap: Transition = { type: "spring", stiffness: 700, damping: 38 };

export const tweenFast: Transition = { duration: 0.18, ease: [0.23, 1, 0.32, 1] };
export const tweenSoft: Transition = { duration: 0.32, ease: [0.23, 1, 0.32, 1] };

export const surface =
  "relative flex h-[150px] w-[230px] max-w-full select-none items-center justify-center text-foreground";

export function usePreviewPulse(
  preview: boolean | undefined,
  duration = 900,
  gap = 2500,
) {
  const [on, setOn] = useState(false);
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) {
      setOn(false);
      return;
    }
    let close = 0;
    let next = 0;
    const run = () => {
      setOn(true);
      close = window.setTimeout(() => setOn(false), duration);
      next = window.setTimeout(run, gap);
    };
    run();
    return () => {
      window.clearTimeout(close);
      window.clearTimeout(next);
    };
  }, [preview, reduce, duration, gap]);

  return on && !reduce;
}

export function usePreviewStep(
  preview: boolean | undefined,
  steps: number,
  interval = 1500,
) {
  const [step, setStep] = useState(0);
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) return;
    setStep(1);
    const id = window.setInterval(
      () => setStep((current) => (current + 1) % steps),
      interval,
    );
    return () => window.clearInterval(id);
  }, [preview, reduce, steps, interval]);

  return reduce ? 0 : step;
}

export function usePreviewPointer(
  preview: boolean | undefined,
  width = 220,
  height = 120,
) {
  const [point, setPoint] = useState({ x: width / 2, y: height / 2 });
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) return;
    let frame = 0;
    let start = 0;
    const loop = (time: number) => {
      if (!start) start = time;
      const t = (time - start) / 1000;
      const x = width / 2 + Math.cos(t * 1.4) * (width * 0.36);
      const y = height / 2 + Math.sin(t * 2.1) * (height * 0.28);
      setPoint({ x, y });
      frame = requestAnimationFrame(loop);
    };
    frame = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frame);
  }, [preview, reduce, width, height]);

  return [point, setPoint] as const;
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

/**
 * The docs stage zooms its children (CSS `zoom`), so a pointer event reports
 * positions in zoomed pixels while the component lays itself out unscaled.
 * Normalise the event back into the component's own coordinate space.
 */
export function localPoint(
  event: { clientX: number; clientY: number },
  node: HTMLElement,
) {
  const rect = node.getBoundingClientRect();
  const scaleX = node.offsetWidth ? rect.width / node.offsetWidth : 1;
  const scaleY = node.offsetHeight ? rect.height / node.offsetHeight : 1;
  return {
    x: (event.clientX - rect.left) / (scaleX || 1),
    y: (event.clientY - rect.top) / (scaleY || 1),
  };
}

export function naturalWidth(node: HTMLElement) {
  return node.offsetWidth || node.getBoundingClientRect().width;
}

export function pointerScaleX(node: HTMLElement) {
  const rect = node.getBoundingClientRect();
  return node.offsetWidth ? rect.width / node.offsetWidth : 1;
}

"use client";

import { Flower2, Leaf, Snowflake, Sun } from "lucide-react";
import { motion } from "motion/react";
import { useId, useRef, useState } from "react";
import {
  cn,
  springSoft,
  surface,
  useHydratedReducedMotion,
  usePreviewStep,
  type MomentProps,
} from "./shared";

const TABS = [
  { label: "Spring", copy: "A soft curve that settles.", Icon: Flower2 },
  { label: "Summer", copy: "Short, warm and direct.", Icon: Sun },
  { label: "Autumn", copy: "A slower, falling rhythm.", Icon: Leaf },
  { label: "Winter", copy: "Still, quiet and exact.", Icon: Snowflake },
];

const SLOT = 44;

export function LeafTabs({ className, preview }: MomentProps) {
  const [active, setActive] = useState(0);
  const baseId = useId();
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const reduce = useHydratedReducedMotion();
  const step = usePreviewStep(preview, TABS.length, 1500);
  const index = preview ? step : active;

  const select = (next: number) => {
    setActive(next);
    tabRefs.current[next]?.focus();
  };

  const key = (event: React.KeyboardEvent) => {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      select((active + 1) % TABS.length);
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      select((active - 1 + TABS.length) % TABS.length);
    }
    if (event.key === "Home") {
      event.preventDefault();
      select(0);
    }
    if (event.key === "End") {
      event.preventDefault();
      select(TABS.length - 1);
    }
  };

  return (
    <div className={cn(surface, "flex-col gap-0", className)}>
      <div
        role="tablist"
        aria-label="Leaf tabs"
        onKeyDown={key}
        className="flex items-end gap-1"
      >
        {TABS.map((tab, tabIndex) => {
          const selected = index === tabIndex;
          return (
            <motion.button
              key={tab.label}
              ref={(node) => {
                tabRefs.current[tabIndex] = node;
              }}
              type="button"
              role="tab"
              id={`${baseId}-tab-${tabIndex}`}
              aria-label={tab.label}
              aria-selected={selected}
              aria-controls={`${baseId}-panel`}
              tabIndex={selected ? 0 : -1}
              onClick={() => setActive(tabIndex)}
              animate={
                reduce
                  ? { y: selected ? -4 : 0, rotate: 0, scale: 1 }
                  : { y: selected ? -9 : 0, rotate: selected ? -5 : 0, scale: selected ? 1.03 : 1 }
              }
              transition={reduce ? { duration: 0 } : springSoft}
              style={{ transformOrigin: "bottom left", width: SLOT }}
              className={cn(
                "flex h-8 items-center justify-center rounded-tl-[18px] rounded-tr-[18px] rounded-b-[7px] border border-b-0 outline-none transition-colors focus-visible:ring-2 focus-visible:ring-white/60",
                selected
                  ? "border-white/20 bg-white text-black shadow-[0_-6px_16px_rgba(0,0,0,.25)]"
                  : "border-white/10 bg-white/8 text-white/45 hover:bg-white/12",
              )}
            >
              <tab.Icon className="size-3.5" strokeWidth={1.8} aria-hidden="true" />
            </motion.button>
          );
        })}
      </div>
      <div
        id={`${baseId}-panel`}
        role="tabpanel"
        aria-labelledby={`${baseId}-tab-${index}`}
        className="flex h-[58px] w-[188px] flex-col justify-center rounded-xl rounded-tl-none border border-white/10 bg-white/8 px-3"
      >
        <motion.span
          key={TABS[index].label}
          initial={reduce ? false : { opacity: 0, x: 4 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: reduce ? 0 : 0.18 }}
          className="text-[12px] font-medium"
        >
          {TABS[index].label}
        </motion.span>
        <motion.span
          key={`${TABS[index].label}-copy`}
          initial={reduce ? false : { opacity: 0, x: 4 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: reduce ? 0 : 0.22, delay: reduce ? 0 : 0.03 }}
          className="mt-0.5 text-[10px] text-white/45"
        >
          {TABS[index].copy}
        </motion.span>
      </div>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function useHydratedReducedMotion() {
  const reduce = useReducedMotion() ?? false;
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  return mounted ? reduce : false;
}
